\label{lem:difference-of-stars}
Let $m,D\geq1$, let $\mathbf a,\mathbf b\in \mathbb{F}_q^m$, and let
$c_0,c_1\in \mathbb{F}_q$. Then
\[
 \{Q-P:P,Q\in\mathcal P_{m,D},\ P(\mathbf a)=c_0,\ Q(\mathbf b)=c_1\}
 =
 \begin{cases}
   \mathcal P_{m,D},&\mathbf a\neq\mathbf b,\\[1mm]
   \{R\in\mathcal P_{m,D}:R(\mathbf a)=c_1-c_0\},
      &\mathbf a=\mathbf b.
 \end{cases}
\]

\label{lem:grid}
Let $\mathbb{F}$ be a finite field, and let $P\in \mathbb{F}[t_1,\ldots,t_m]$. If
$\deg_{t_i}P<|\mathbb{F}|$ for every $i$ and $P$ vanishes on $\mathbb{F}^m$, then $P=0$.

\label{prop:degree-one}
The space $\mathcal P_{n,1}$ has the strict EKR property if and only if
$q=2$ and $n=1$.

\label{thm:F2-pairwise}
The space $\mathcal P_{n,d}$ over $\mathbb{F}_2$ has the strict EKR
property if and only if $n=1$.

\label{thm:threewise-qge3}
Let $q\geq3$ and let $n,d\geq1$. Every maximum 3-wise intersecting
family in $\mathcal P_{n,d}$ is a star.

\label{thm:threewise-F2}
Let $n\geq 1$ and $d\geq2$. Every maximum 3-wise intersecting family
in $\mathcal P_{n,d}$ over $\mathbb{F}_2$ is a star.

\label{lem:norm-coefficient-separation}
Let $s\geq1$, let $\mathbf y=(y_1,\ldots,y_s)$, and let
$\boldsymbol{\beta}=(\beta_1,\ldots,\beta_s)\in \mathbb{F}_{q^d}^s$. As $\boldsymbol{\beta}$ ranges over $\mathbb{F}_{q^d}^s$, the forms $\operatorname{N}(\beta_1y_1+\cdots+\beta_sy_s)$ span $\mathcal H_{s,d}$.

\label{prop:quadratic}
Let $q$ be odd and $n\geq1$. Every maximum intersecting family in
$\mathcal P_{n,2}$ is a star.

\label{prop:critical-even}
Let $q\geq4$ be even and let $n\geq1$. Every maximum intersecting
family in $\mathcal P_{n,n+1}$ is a star.

\label{prop:even-fiber-rigidity}
Let $q\geq4$ be even and let $2\leq d\leq n$. Every maximum
intersecting family in $\mathcal K_{n,d}$ is a star.

\label{prop:even-exceptional-classification}
Let $q\geq4$ be even and let $2\leq d\leq n$. For each
$\omega\in\mathcal M_{n,d}$, choose a pair $(\mathbf s_\omega,c_\omega)\in \mathbb{F}_q^n\times \mathbb{F}_q$, and set $\mathbf{s}=(\mathbf{s}_{\omega})_{\omega\in \mathcal M_{n,d}}$ and $c=(c_{\omega})_{\omega\in \mathcal M_{n,d}}$. Then
\begin{equation}\label{eq:even-exceptional-family}
  \mathcal F_{\mathbf s,c}
  =\bigcup_{\omega\in\mathcal M_{n,d}}
    \{f\in\mathcal P_{n,d}:\Omega_{n,d}(f)=\omega,
       \ f(\mathbf s_\omega)=c_\omega\}
\end{equation}
is a maximum intersecting family. Conversely, every maximum
intersecting family in $\mathcal P_{n,d}$ has a unique representation of the
form \eqref{eq:even-exceptional-family}.

\label{thm:even-exceptional}
Let $q\geq4$ be even and let $2\leq d\leq n$. Then
$\mathcal P_{n,d}$ does not have the strict EKR property.
